content:
Review this change for security vulnerabilities.

Changed files (you may Read these and any other file in the repo):
  - macapp/WorkroomApp/Core/AppStore.swift
  - macapp/WorkroomApp/Core/ThemePanel.swift
  - macapp/WorkroomApp/Core/ThemeService.swift
  - macapp/WorkroomApp/Views/KeyboardShortcutsView.swift
  - macapp/WorkroomApp/Views/RootView.swift
  - macapp/WorkroomApp/Views/ThemePicker.swift
  - macapp/WorkroomApp/Views/TitlebarBars.swift
  - macapp/WorkroomApp/WorkroomApp.swift
  - macapp/WorkroomAppTests/SwitcherThemeSweepTests.swift
  - macapp/WorkroomAppTests/ThemePanelTests.swift
  - macapp/WorkroomAppTests/ThemeServiceTests.swift
  - macapp/WorkroomAppUITests/ThemePickerUITests.swift

Unified diff (only + lines are new):

=== DIFF: macapp/WorkroomApp/Core/AppStore.swift ===
@@ -575,8 +575,9 @@ final class AppStore: ObservableObject {
   /// Drives the immediate full-pane setup dialog AND the provisional "Creating…" tab chip — both
   /// appear before the CLI has even reported the (generated) name. Per-window, like selection.
   @Published var creation: WorkroomCreation?
-  /// Mirrors whether one of RootView's *view-local* sheets is up (Add Project, Theme Picker, Keyboard
-  /// Shortcuts, What's New). Those four are `@State` in RootView rather than store-level like the
+  /// Mirrors whether one of RootView's *view-local* sheets is up (Add Project, Keyboard Shortcuts,
+  /// What's New — the theme dropdown is a transient popover, not modal, and deliberately NOT counted:
+  /// it closes itself when one of these comes up). Those are `@State` in RootView rather than the
   /// `pending*` ones, so `hasModalPresentation` can't see them directly; RootView keeps this in sync
   /// with a single `onChange`. Deliberately a mirror rather than re-homing the four flags onto the
   /// store: re-homing a local sheet flag to a store-level published item needs a clobber guard to stop


=== DIFF: macapp/WorkroomApp/Core/ThemePanel.swift ===
@@ -1,184 +0,0 @@
-import AppKit
-import SwiftUI
-
-/// The theme picker's window (issue #36) — a floating, movable utility panel.
-///
-/// **Why this isn't the `.sheet` it used to be.** Choosing a theme is a live-preview gesture: ↑/↓
-/// apply families as you move through them, so the app *behind* the picker is the preview. A sheet
-/// defeated that twice over, both measured on the real build:
-///
-/// - **It faded the app.** A sheet is document-modal, so AppKit disables and inactive-renders the
-///   window it's attached to. Side-by-side captures of the same window: traffic lights greyed out,
-///   the sidebar's VCS dot badges went from orange to a dull brown, and the detail placeholder
-///   washed out. You were judging a theme against colours the app never shows while you use it.
-/// - **It couldn't be moved.** A sheet is anchored under its window's title bar, so it sat on top of
-///   the content whose colours you were trying to see, with nothing to drag.
-///
-/// An `NSPanel` fixes both: `NSPanel` refuses to become the *main* window, so the workroom window
-/// keeps `isMainWindow` and goes on drawing active while this panel holds the keyboard, and a titled
-/// panel drags anywhere on screen — including clear of the window entirely.
-///
-/// `SwitcherPanel` is the app's other panel and the mirror image of this one: it must *never* take
-/// key focus (the ⌥Tab gesture depends on the workroom window keeping it), whereas this one must,
-/// because the search field and the live-apply ↑/↓ keys are the whole interaction.
-final class ThemePanel: NSPanel {
-  /// Esc closes, matching the sheet this replaces. `NSWindow` routes `cancelOperation` to a close for
-  /// sheets and modal panels only, so a floating panel has to opt in.
-  override func cancelOperation(_ sender: Any?) { performClose(sender) }
-}
-
-/// Owns the one theme panel. App-level rather than per-window: a theme is an app-wide preference
-/// (`Defaults[.themeFamily]`), so a second picker on a second window could only ever disagree with
-/// the first.
-@MainActor
-final class ThemePanelController {
-  static let shared = ThemePanelController()
-
-  /// Content size — the frame `ThemePicker` gives itself. Same width as the sheet this replaces; the
-  /// height is the sheet's minus the in-view title row that the panel's real title bar takes over.
-  static let contentSize = CGSize(width: 300, height: 420)
-
-  /// Inset from the anchor window's top-trailing corner for a first-ever open. After that the panel
-  /// remembers wherever the user dragged it (`frameAutosaveName`), which is the point of a panel —
-  /// so the default only has to be somewhere sane, and the trailing edge keeps the sidebar and the
-  /// focused terminal (the two surfaces a theme is judged on) unobstructed.
-  private static let defaultInset: CGFloat = 24
-
-  static let frameAutosaveName = "workroom.theme.panel"
-
-  /// Where AppKit persists `frameAutosaveName`. Exposed so `ThemePanelTests` can put the developer's
-  /// own saved position back: a unit test that opens the panel writes this key into the app host's
-  /// domain (`UserDefaults`, so no `$HOME` isolates it), which would otherwise mean running the suite
-  /// silently moves where your picker opens.
-  static var frameAutosaveDefaultsKey: String { "NSWindow Frame \(frameAutosaveName)" }
-
-  private var panel: ThemePanel?
-  private var commandObserver: NSObjectProtocol?
-  private var themeObserver: NSObjectProtocol?
-
-  deinit {
-    // Only `shared` lives for the process, but tests make their own instances — an un-removed block
-    // observer is retained by the notification centre for the process's lifetime.
-    if let commandObserver { NotificationCenter.default.removeObserver(commandObserver) }
-    if let themeObserver { NotificationCenter.default.removeObserver(themeObserver) }
-  }
-
-  /// Start observing the `Theme…` (⌘⇧K) command. Called once at launch.
-  ///
-  /// App-level, not per-`RootView`: presenting the sheet was guarded on `hostWindow?.isKeyWindow` (a
-  /// broadcast notification would otherwise pop a sheet in every window), and once this panel is key
-  /// no window passes that guard — so a window-scoped observer could never close or re-raise it.
-  func attach() {
-    guard commandObserver == nil else { return }
-    commandObserver = NotificationCenter.default.addObserver(
-      forName: .showThemePicker, object: nil, queue: .main
-    ) { _ in
-      MainActor.assumeIsolated { ThemePanelController.shared.toggle() }
-    }
-  }
-
-  /// ⌘⇧K opens, and pressing it again closes — the panel is non-modal and floats above the window, so
-  /// the shortcut that summoned it has to be able to get rid of it too.
-  func toggle() {
-    if let panel, panel.isVisible {
-      panel.performClose(nil)
-      return
-    }
-    show()
-  }
-
-  /// Whether this controller's panel is on screen. Tests read it instead of counting
-  /// `NSApp.windows`, which is process-wide and so racy under the parallel test runner.
-  var isPanelVisible: Bool { panel?.isVisible ?? false }
-
-  func show() {
-    let panel = panel ?? makePanel()
-    self.panel = panel
-    if !panel.isVisible { positionIfNeeded(panel) }
-    panel.makeKeyAndOrderFront(nil)
-  }
-
-  /// Build the panel, ordered out. Not private: `ThemePanelTests` asserts the **production**
-  /// configuration through this, rather than re-declaring a panel in the test and checking the
-  /// properties it just set itself.
-  func makePanel() -> ThemePanel {
-    let panel = ThemePanel(
-      contentRect: NSRect(origin: .zero, size: Self.contentSize),
-      // No `.resizable`: the content is a fixed-width list, and the picker frames itself.
-      styleMask: [.titled, .closable, .utilityWindow], backing: .buffered, defer: false)
-    panel.title = "Theme"
-    // Floats above the workroom window, so clicking a row (which hands key focus back) can't bury the
-    // panel behind the window whose colours it is changing.
-    panel.isFloatingPanel = true
-    // Usable over a full-screen workroom window; without this the panel simply never shows there.
-    panel.collectionBehavior.insert(.fullScreenAuxiliary)
-    panel.isReleasedWhenClosed = false
-    // The Window menu lists workroom windows; a palette reachable by ⌘⇧K doesn't belong in it.
-    panel.isExcludedFromWindowsMenu = true
-    panel.setAccessibilityIdentifier("theme.panel")
-    // Same panel colour the title bar and chrome take (`WindowBackgroundThemer`), re-applied on a
-    // theme change — which, for this window, is every arrow key.
-    applyTheme(to: panel)
-    themeObserver = NotificationCenter.default.addObserver(
-      forName: .themeDidChange, object: nil, queue: .main
-    ) { [weak self, weak panel] _ in
-      MainActor.assumeIsolated {
-        guard let self, let panel else { return }
-        self.applyTheme(to: panel)
-      }
-    }
-
-    let host = NSHostingView(rootView: ThemePicker(onDone: { [weak panel] in panel?.close() }))
-    host.autoresizingMask = [.width, .height]
-    panel.contentView = host
-    return panel
-  }
-
-  private func applyTheme(to panel: NSPanel) {
-    panel.backgroundColor = ThemeService.shared.tokens.nsPanel
-  }
-
-  /// Restore the user's own placement, else park the panel at the anchor window's top-trailing corner.
-  ///
-  /// `setFrameUsingName` is checked rather than trusted: a frame saved on a monitor that is no longer
-  /// attached restores off-screen, and a panel the user cannot see is a panel they cannot close.
-  private func positionIfNeeded(_ panel: ThemePanel) {
-    // Both the save and the restore are skipped under the UI-test fixture: the frame lands in
-    // `UserDefaults`, which `cfprefsd` resolves against the real home whatever `$HOME` a test run sets.
-    // So a test that drags the panel would move where it opens for the developer, permanently — and a
-    // developer who had dragged theirs would hand the test a different starting position.
-    if !UITestFixture.isActive {
-      panel.setFrameAutosaveName(Self.frameAutosaveName)
-      let screens = NSScreen.screens.map(\.visibleFrame)
-      if panel.setFrameUsingName(Self.frameAutosaveName),
-        Self.isOnScreen(panel.frame, screens: screens)
-      {
-        return
-      }
-    }
-    let size = panel.frame.size
-    let origin = Self.defaultOrigin(
-      size: size, anchor: NSApp.mainWindow?.frame, visible: NSScreen.main?.visibleFrame)
-    panel.setFrame(NSRect(origin: origin, size: size), display: false)
-  }
-
-  /// Whether `frame` overlaps a visible area of some attached screen.
-  static func isOnScreen(_ frame: NSRect, screens: [NSRect]) -> Bool {
-    screens.contains { $0.intersects(frame) }
-  }
-
-  /// Top-trailing corner of the window a theme would be judged against — the main window (never this
-  /// panel, which cannot become main), falling back to the screen when no window is open.
-  static func defaultOrigin(size: CGSize, anchor: NSRect?, visible: NSRect?) -> CGPoint {
-    let bounds = anchor ?? visible ?? NSRect(x: 0, y: 0, width: 1440, height: 900)
-    var origin = CGPoint(
-      x: bounds.maxX - size.width - defaultInset, y: bounds.maxY - size.height - defaultInset)
-    // Clamp into the screen: a workroom window can sit partly off the right edge, and the panel
-    // would inherit that.
-    if let visible {
-      origin.x = min(max(origin.x, visible.minX), max(visible.maxX - size.width, visible.minX))
-      origin.y = min(max(origin.y, visible.minY), max(visible.maxY - size.height, visible.minY))
-    }
-    return origin
-  }
-}


